INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(909958, 104951, 12253, '<td valign="top">Very clever.  I wonder if you tried it the other way around with focus--and perhaps a little closer to the mirror.  I think it would have been more subtle and might have been better that way (though many mightt not have caught it in the brief time they look.)  Lastly, light seems very flat, a little directional lighting would ahve been nice.</td>', 'Very clever.  I wonder if you tried it the other way around with focus--and perhaps a little closer to the mirror.  I think it would have been more subtle and might have been better that way (though many mightt not have caught it in the brief time they look.)  Lastly, light seems very flat, a little directional lighting would ahve been nice.', '2004-09-14 21:10:02.000000', NULL, 1),
(909959, 105020, 26464, '<td valign="top">great concept, would be cool if the eyes reflected something else appropriate to the title though... <br/>or maybe i''m missing the point?<br/></td>', 'great concept, would be cool if the eyes reflected something else appropriate to the title though... or maybe i''m missing the point?', '2004-09-14 21:10:06.000000', NULL, 1),
