(909989, 104649, 25754, '<td valign="top">This is a nice shot, I really like the light. On my monitor I can see rectangular patches where you have done some spot editing, as well as a dark strip going straight across the top of the image. Unfortunately that takes away from the overall impact of the photo.</td>', 'This is a nice shot, I really like the light. On my monitor I can see rectangular patches where you have done some spot editing, as well as a dark strip going straight across the top of the image. Unfortunately that takes away from the overall impact of the photo.', '2004-09-14 21:38:34.000000', NULL, 1),
(909995, 103808, 24642, '<td valign="top">Wow this is fantastic.  Great idea, strong and simple title, good tones.  The mirror is not a major element in the picture, the shot would be good without it.</td>', 'Wow this is fantastic.  Great idea, strong and simple title, good tones.  The mirror is not a major element in the picture, the shot would be good without it.', '2004-09-14 21:45:18.000000', NULL, 1),
