(911712, 105030, 12362, '<td valign="top">The colors in this shot are ABSOLUTELY BEAUTIFUL!!!, This is a very nice idea. 8</td>', 'The colors in this shot are ABSOLUTELY BEAUTIFUL!!!, This is a very nice idea. 8', '2004-09-15 16:19:45.000000', NULL, 1),
(911713, 104795, 12362, '<td valign="top">The texture and detail in this shot does it for me. The sepia works VERY well, great use of the rule of thirds. 9</td>', 'The texture and detail in this shot does it for me. The sepia works VERY well, great use of the rule of thirds. 9', '2004-09-15 16:20:32.000000', NULL, 1),
