(912625, 105020, 20375, '<td valign="top">This shot jumped out at me! Very creative, excellent composition!<br/>Good choice on the desat. I love it!  9 from me. Got my fingers crossed for you on this to ribbon!</td>', 'This shot jumped out at me! Very creative, excellent composition!Good choice on the desat. I love it!  9 from me. Got my fingers crossed for you on this to ribbon!', '2004-09-16 04:03:51.000000', NULL, 1),
(912626, 105015, 20375, '<td valign="top">Excellent perspective shot. I love the way you''ve concentrated your shot on the mirror (meets the challenge) yet the out of focus dancers addl a story to the shot. Actuall its nostalgic for me......highschool dances under the mirrored ball lighting effect......ahhhh to be young again. -9</td>', 'Excellent perspective shot. I love the way you''ve concentrated your shot on the mirror (meets the challenge) yet the out of focus dancers addl a story to the shot. Actuall its nostalgic for me......highschool dances under the mirrored ball lighting effect......ahhhh to be young again. -9', '2004-09-16 04:06:14.000000', NULL, 1),
(912627, 104649, 8054, '<td valign="top">A bit too centered and looks slightly overprocessed. I would leave some negative space on the right side of the frame and maybe a bit more at the top.</td>', 'A bit too centered and looks slightly overprocessed. I would leave some negative space on the right side of the frame and maybe a bit more at the top.', '2004-09-16 04:06:37.000000', NULL, 1),
