(914682, 105126, 10848, '<td valign="top">Very creative,nice</td>', 'Very creative,nice', '2004-09-17 16:16:44.000000', NULL, 1),
(914685, 105040, 21643, '<td valign="top">This is such an interesting shot, because there are three unique and distinct objects, yet none of them distract from the others. Very original setup!<br/></td>', 'This is such an interesting shot, because there are three unique and distinct objects, yet none of them distract from the others. Very original setup!', '2004-09-17 16:20:34.000000', NULL, 1),
(914833, 105032, 24016, '<td valign="top">cool shot. nice angle, it looks surreal. nice colours emphasizing the shapes.</td>', 'cool shot. nice angle, it looks surreal. nice colours emphasizing the shapes.', '2004-09-17 18:14:58.000000', NULL, 1),
(914839, 105046, 24016, '<td valign="top">very nice take on a challenge. i like the distorted geometry in the reflections. not sure if the image was heavily manipulated, but if it was, it still works well.</td>', 'very nice take on a challenge. i like the distorted geometry in the reflections. not sure if the image was heavily manipulated, but if it was, it still works well.', '2004-09-17 18:16:53.000000', NULL, 1),
(914842, 105040, 24016, '<td valign="top">very nice capture. i like the contrast of colours and shapes in the real/reflected parts of the image, and that plane looks awesome! high marks from me.</td>', 'very nice capture. i like the contrast of colours and shapes in the real/reflected parts of the image, and that plane looks awesome! high marks from me.', '2004-09-17 18:18:01.000000', NULL, 1),
(914849, 103736, 24016, '<td valign="top">i really like the light rays sprinkled on the model.  "mermerised" emotion captured very well as well.</td>', 'i really like the light rays sprinkled on the model.  "mermerised" emotion captured very well as well.', '2004-09-17 18:21:42.000000', NULL, 1),
(914853, 105087, 24016, '<td valign="top">the only thing that does not work for me in this photograph is the frame. it seems a bit out of place on an otherwise excellent composition. the "past" mood of this photograph is very well done. i also like the superposition of bricks reflected in the mirror on the wall.</td>', 'the only thing that does not work for me in this photograph is the frame. it seems a bit out of place on an otherwise excellent composition. the "past" mood of this photograph is very well done. i also like the superposition of bricks reflected in the mirror on the wall.', '2004-09-17 18:24:51.000000', NULL, 1),
(914883, 105002, 20941, '<td valign="top">the colors are great, focus on feather and its mirror image are sharp, very nice!</td>', 'the colors are great, focus on feather and its mirror image are sharp, very nice!', '2004-09-17 18:39:11.000000', NULL, 1),
(914887, 104735, 20941, '<td valign="top">very cool, love its surreal look</td>', 'very cool, love its surreal look', '2004-09-17 18:44:08.000000', NULL, 1),
(914894, 104252, 20941, '<td valign="top">love your composition, the pink tie is an excellent touch. Beautiful work.</td>', 'love your composition, the pink tie is an excellent touch. Beautiful work.', '2004-09-17 18:47:42.000000', NULL, 1),
(914897, 105108, 5286, '<td valign="top">Nicely focused, and nice timiing! Though, I feel that a tighter crop would have benefitted this image...</td>', 'Nicely focused, and nice timiing! Though, I feel that a tighter crop would have benefitted this image...', '2004-09-17 18:54:20.000000', NULL, 1),
(914900, 104860, 5286, '<td valign="top">Nice capture! Not sure I like the color in the mirror though... it sort of clashes with the snail''s colors.</td>', 'Nice capture! Not sure I like the color in the mirror though... it sort of clashes with the snail''s colors.', '2004-09-17 18:55:22.000000', NULL, 1),
(914902, 105038, 5286, '<td valign="top">Very nicely done. I wanted to do something like this too, you''ve done a great job!! Pity you had to leave the frame in to make the mirror evident. 9.</td>', 'Very nicely done. I wanted to do something like this too, you''ve done a great job!! Pity you had to leave the frame in to make the mirror evident. 9.', '2004-09-17 18:57:34.000000', NULL, 1),
(914959, 105002, 19608, '<td valign="top">Very nice, great DoF and excellent colors.  A true study in texture as well.</td>', 'Very nice, great DoF and excellent colors.  A true study in texture as well.', '2004-09-17 20:00:33.000000', NULL, 1),
(914961, 103850, 19608, '<td valign="top">Your idea is superb, but the execution needs some work.  The hot white areas pretty much ruins an otherwise nice effort.</td>', 'Your idea is superb, but the execution needs some work.  The hot white areas pretty much ruins an otherwise nice effort.', '2004-09-17 20:02:09.000000', NULL, 1),
(914964, 104756, 19608, '<td valign="top">Nice macro - most likely way better than 1:1.  Mirrir is not evident to me.</td>', 'Nice macro - most likely way better than 1:1.  Mirrir is not evident to me.', '2004-09-17 20:03:41.000000', NULL, 1),
(914965, 105027, 19608, '<td valign="top">My first impression of this was "I wonder how that was done?"  Then I started studying it and found it has a lot going for it.  The composition and ever-shrinking shapes on the left are great.  The several white hot spots are terrible.  The overall feel is that of a very artistic mystery.</td>', 'My first impression of this was "I wonder how that was done?"  Then I started studying it and found it has a lot going for it.  The composition and ever-shrinking shapes on the left are great.  The several white hot spots are terrible.  The overall feel is that of a very artistic mystery.', '2004-09-17 20:08:51.000000', NULL, 1),
(914967, 104781, 19608, '<td valign="top">Nice colors which are really nice.  On the other hand, the busy composition and lack of more area in focus are not so nice.</td>', 'Nice colors which are really nice.  On the other hand, the busy composition and lack of more area in focus are not so nice.', '2004-09-17 20:10:21.000000', NULL, 1),
(914969, 104349, 19608, '<td valign="top">Interesting and aristic.  Colors are nice - color transitions seem a bit weird.</td>', 'Interesting and aristic.  Colors are nice - color transitions seem a bit weird.', '2004-09-17 20:12:14.000000', NULL, 1),
(914972, 105136, 19608, '<td valign="top">Great idea and setup, perfect exposure.  The costume on your model is great for the background.  I don''t think the pointed index finger does anything and wonder why you had her pose that way.  Overall - you should finish way up in the pack.</td>', 'Great idea and setup, perfect exposure.  The costume on your model is great for the background.  I don''t think the pointed index finger does anything and wonder why you had her pose that way.  Overall - you should finish way up in the pack.', '2004-09-17 20:18:21.000000', NULL, 1),
(914974, 104110, 19608, '<td valign="top">Funny - and nicely done.  Exposure spot on.</td>', 'Funny - and nicely done.  Exposure spot on.', '2004-09-17 20:19:35.000000', NULL, 1),
(914975, 104917, 19608, '<td valign="top">Nicely done.  What are the red spots on the eggs and why did you include them (it doesn''t help.)  The dark blue plate is perfect for the yellow egg yolk.</td>', 'Nicely done.  What are the red spots on the eggs and why did you include them (it doesn''t help.)  The dark blue plate is perfect for the yellow egg yolk.', '2004-09-17 20:21:21.000000', NULL, 1),
(914979, 104951, 19608, '<td valign="top">Exceptional idea and well planned.  My problem with your image is the total "muddiness" of the b&amp;w.  There are no real whites, few real blacks, and a very limited tonal range of grays.  So - you get VERY high marks for the idea and the emotional image, but they are then reduced by the technical execution.  The final result - it''s one of my top ten.</td>', 'Exceptional idea and well planned.  My problem with your image is the total "muddiness" of the b&w.  There are no real whites, few real blacks, and a very limited tonal range of grays.  So - you get VERY high marks for the idea and the emotional image, but they are then reduced by the technical execution.  The final result - it''s one of my top ten.', '2004-09-17 20:25:31.000000', NULL, 1),
(914980, 105002, 24976, '<td valign="top">wow, this is the best ive seen in the challenge so far! definetly my top ribbon pick. There is nothing wrong with it in my eyes... its a perfect 10</td>', 'wow, this is the best ive seen in the challenge so far! definetly my top ribbon pick. There is nothing wrong with it in my eyes... its a perfect 10', '2004-09-17 20:25:54.000000', NULL, 1),
(914982, 104163, 19608, '<td valign="top">Very colorful and graphic.  Nice lines and use of the image space.  In my top 10.</td>', 'Very colorful and graphic.  Nice lines and use of the image space.  In my top 10.', '2004-09-17 20:26:40.000000', NULL, 1),
(914984, 105046, 24976, '<td valign="top">beautiful abstraction. I love the fluidity and dymanism the reflected lines have. And i also like the composition in general. 9</td>', 'beautiful abstraction. I love the fluidity and dymanism the reflected lines have. And i also like the composition in general. 9', '2004-09-17 20:27:56.000000', NULL, 1),
(914986, 103616, 19608, '<td valign="top">Great idea, although not exactly a mirror.  Nice colors, perfect model and expression.</td>', 'Great idea, although not exactly a mirror.  Nice colors, perfect model and expression.', '2004-09-17 20:33:22.000000', NULL, 1),
(914988, 105010, 19608, '<td valign="top">Don''t know what it is - but it really works.  White background is perfect albeit it conflicts with the title big time.</td>', 'Don''t know what it is - but it really works.  White background is perfect albeit it conflicts with the title big time.', '2004-09-17 20:35:32.000000', NULL, 1),
(915002, 103736, 19608, '<td valign="top">A well-done study of the lad.  Nice job.</td>', 'A well-done study of the lad.  Nice job.', '2004-09-17 20:42:55.000000', NULL, 1),
(915007, 105025, 19608, '<td valign="top">A real artistic take on the challenge.  The use of desat on the "real" landscape is perfect.</td>', 'A real artistic take on the challenge.  The use of desat on the "real" landscape is perfect.', '2004-09-17 20:45:43.000000', NULL, 1),
(915016, 104939, 19608, '<td valign="top">Nostalgia!  Many of our younger viewers will be scratching their heads saying, "Huh?"  Nice job, nice reflection.  Some may say the mirror isn''t "obvious."</td>', 'Nostalgia!  Many of our younger viewers will be scratching their heads saying, "Huh?"  Nice job, nice reflection.  Some may say the mirror isn''t "obvious."', '2004-09-17 20:49:42.000000', NULL, 1);
