(916263, 105075, 23300, '<td valign="top">I love this image. Its very evocative. I think the desaturation helps to enhance the emotion of the image. The composition and lighting all help to enhance the emotional impact.</td>', 'I love this image. Its very evocative. I think the desaturation helps to enhance the emotion of the image. The composition and lighting all help to enhance the emotional impact.', '2004-09-19 02:51:26.000000', NULL, 1),
(916264, 104999, 23300, '<td valign="top">Lovely colouring and lighting. The colours and tones in this image all work well together. The compostion works well to enhance the subject matter. The central composition works well.</td>', 'Lovely colouring and lighting. The colours and tones in this image all work well together. The compostion works well to enhance the subject matter. The central composition works well.', '2004-09-19 02:55:07.000000', NULL, 1),
